# Pyodide menjalankan kode dengan __name__ = "builtins".
# Baris berikut menyamakannya dengan Python biasa.
if __name__ == "builtins":
    __name__ = "__main__"


antrean_input = [
    "1",
    "2", "Belajar Python", "Rina", "2025", "5",
    "3", "1", "Python Dasar Edisi 2", "Andi", "2024", "4",
    "1",
    "4", "2", "y",
    "1",
    "5",
]


def input_simulasi(prompt=""):
    print(prompt, end="")
    if not antrean_input:
        print("(antrean input habis)")
        return "5"
    jawaban = antrean_input.pop(0)
    print(jawaban)
    return jawaban


daftar_buku = [
    {"judul": "Python Dasar", "penulis": "Andi", "tahun": 2024, "stok": 3},
    {"judul": "Algoritma", "penulis": "Budi", "tahun": 2023, "stok": 2},
]


def show_data():
    print("\nDAFTAR BUKU")
    if not daftar_buku:
        print("Belum ada buku.")
        return

    for nomor, buku in enumerate(daftar_buku, start=1):
        print(
            f"{nomor}. {buku['judul']} | {buku['penulis']} | "
            f"{buku['tahun']} | stok {buku['stok']}"
        )


def insert_data():
    print("\nTAMBAH BUKU")
    judul = input_simulasi("Judul: ")
    penulis = input_simulasi("Penulis: ")

    try:
        tahun = int(input_simulasi("Tahun: "))
        stok = int(input_simulasi("Stok: "))
    except ValueError:
        print("Tahun dan stok harus berupa angka.")
        return

    daftar_buku.append(
        {
            "judul": judul,
            "penulis": penulis,
            "tahun": tahun,
            "stok": stok,
        }
    )
    print(f"Buku '{judul}' berhasil ditambahkan.")


def edit_data():
    print("\nUBAH BUKU")
    if not daftar_buku:
        print("Belum ada buku.")
        return

    show_data()

    try:
        nomor = int(input_simulasi("Nomor buku: "))
    except ValueError:
        print("Nomor buku harus berupa angka.")
        return

    if nomor < 1 or nomor > len(daftar_buku):
        print("Nomor buku tidak valid.")
        return

    judul = input_simulasi("Judul: ")
    penulis = input_simulasi("Penulis: ")

    try:
        tahun = int(input_simulasi("Tahun: "))
        stok = int(input_simulasi("Stok: "))
    except ValueError:
        print("Tahun dan stok harus berupa angka.")
        return

    daftar_buku[nomor - 1] = {
        "judul": judul,
        "penulis": penulis,
        "tahun": tahun,
        "stok": stok,
    }
    print(f"Buku '{judul}' berhasil diubah.")


def delete_data():
    print("\nHAPUS BUKU")
    if not daftar_buku:
        print("Belum ada buku.")
        return

    show_data()

    try:
        nomor = int(input_simulasi("Nomor buku: "))
    except ValueError:
        print("Nomor buku harus berupa angka.")
        return

    if nomor < 1 or nomor > len(daftar_buku):
        print("Nomor buku tidak valid.")
        return

    konfirmasi = input_simulasi("Yakin hapus? (y/n): ").lower()
    if konfirmasi != "y":
        print("Penghapusan dibatalkan.")
        return

    buku = daftar_buku.pop(nomor - 1)
    print(f"Buku '{buku['judul']}' berhasil dihapus.")


def show_menu():
    print("\n=== PUSTAKA MINI ===")
    print("1. Tampilkan  2. Tambah  3. Ubah  4. Hapus  5. Keluar")


def exit():
    print("Terima kasih telah menggunakan Pustaka Mini.")
    return False


def main():
    while True:
        show_menu()
        pilihan = input_simulasi("Pilih menu (1-5): ")

        if pilihan == "1":
            show_data()
        elif pilihan == "2":
            insert_data()
        elif pilihan == "3":
            edit_data()
        elif pilihan == "4":
            delete_data()
        elif pilihan == "5":
            if not exit():
                break
        else:
            print("Pilihan tidak valid. Silakan pilih 1-5.")


if __name__ == "__main__":
    main()
